"""Localized access decisions and attributed handheld reports, October 2026."""
import re


def apply_access(ctx):
    pages, P = ctx['PAGES'], ctx['P']
    article, table, ref, ext = (ctx[k] for k in ['article', 'table', 'ref', 'ext'])
    old_date, old_version = ctx['DATE'], ctx['VERSION']
    ctx['DATE'], ctx['VERSION'] = 'October 28, 2026', 'v0.8.62 entry / v0.8.55 mechanics'
    legal = ('https://pokebonk.com/legal', 'pokebonk.com — project legal notice', 'Rechecked October 28, 2026. Author statement, not an independent security audit.')
    client = ('https://pokebonk.com/assets/main-D2_otW26-mvob1c8t.js', 'pokebonk.com — v0.8.55 public client', 'Mechanics snapshot inspected October 26; not a complete-run test of v0.8.62.')
    ko = ('https://pokebonk.com/?lang=ko', 'pokebonk.com — 한국어 원작', 'October 28 menu inspection: v0.8.62, 게스트 / 입장 / 계정 만들기. No run completed.')
    es = ('https://pokebonk.com/?lang=es', 'pokebonk.com — juego original en español', 'Browser entry and JavaScript/WebGL requirement, checked October 28.')
    report = ('https://www.reddit.com/r/SteamDeck/comments/1xgxauy/pokebonk_runs_well_on_deck/', 'Reddit r/SteamDeck — R3APER_PL and replies', 'Read October 28, 2026. One thread: OP Brave setup, another user’s Heroic route, and unresolved movement reports. Game build and hardware revisions unspecified.')
    article('ko/beginners-guide', '포케봉크 공략: 시작 방법·다운로드·조작', '포케봉크 처음 시작하는 방법',
        '포케봉크 한국어 원작에서 게스트로 시작하고, 기본 조작과 스타터 선택을 확인하세요. 모바일·다운로드·저장 문제는 증상에 따라 구분합니다.',
        f'포케봉크는 브라우저에서 실행하는 비공식 포켓몬 팬 게임입니다. 원작의 한국어 페이지에서 처음이라면 게스트, 기존 계정이 있다면 입장을 선택하세요. 다운로드 파일이나 Megabonk 모드는 필요하지 않습니다.{ref(1)}{ref(2)}', [
        ('start', '원작에서 시작하기', f'<ol><li>{ext(ko[0], "pokebonk.com — 한국어 원작")}을 여세요.</li><li>처음이면 <strong>게스트 → 손님으로 플레이!</strong>를 선택하세요. 기존 계정은 <strong>입장</strong>, 새 계정은 <strong>계정 만들기</strong> 탭입니다.</li><li>파트너와 이용 가능한 모드·맵을 확인한 뒤 시작하세요. 먼저 조작을 익히고 긴 생존 기록에 도전하세요.</li></ol><p>메뉴는 2026년 10월 28일 v0.8.62에서 확인했습니다. 아래 조작·파트너 설명은 v0.8.55 공개 클라이언트 자료입니다. 실제 기기 플레이나 완주 검증은 하지 않았습니다.</p>'),
        ('choose', '스타터는 지금 필요한 역할로 고르기', table(['원하는 방향', '후보', '선택 전 확인'], [('회복을 배우기', '이상해씨 / Bulbasaur', '풀 공격과 회복 효과를 함께 확인하세요. 회복에는 발동 제한이 있습니다.'), ('방어 여유', '꼬부기 / Squirtle', '방어·보호막과 저체력 조건부 공격 보너스는 다른 효과입니다.'), ('불꽃 중심 공격', '파이리 / Charmander', '불꽃 타입 보너스와 물리·특수 피해 보너스의 적용 범위를 구분하세요.')]) + f'<p>승률 순위가 아니라 패시브 기반 선택 도움입니다. 진화 조건은 본가 포켓몬의 레벨을 그대로 적용하지 말고 <a href="/pokebonk/evolution/">이 게임의 진화표 (영어)</a>를 확인하세요.{ref(3)}</p>'),
        ('controls', '기본 조작과 화면 확인', table(['행동', '기본 입력', '확인할 점'], [('이동 / 시점', 'WASD / 마우스', '게임 화면을 클릭해 입력 초점을 돌려주세요.'), ('점프 / 슬라이드', 'Space / 왼쪽 Shift', '설정에서 변경했다면 현재 지정 키가 우선입니다.'), ('상호작용 / 얼티밋', 'E / R', '근처 상호작용 표시와 준비 상태를 확인하세요.'), ('지도 / 일시정지 메뉴', 'M / P', '협동에서는 자신의 메뉴가 세션 전체를 멈추지 않습니다.')]) + f'<p>레벨업 때는 현재 부족한 부분부터 읽으세요. 자주 쓰러지면 회복·방어 효과가 지금 발동하는지, 적을 못 잡으면 선택한 공격의 타입과 피해 분류에 적용되는지 확인하세요.{ref(3)}</p>'),
        ('help', '다운로드·모바일·저장 문제 구분', table(['상황', '다음 행동', '피해야 할 오해'], [('APK나 앱을 찾는 중', '원작 브라우저 경로로 먼저 접속', '공식 안내는 다운로드·앱스토어 배포가 없다고 설명합니다.'), ('휴대폰에서 버튼이 작음', '가로 화면과 게임의 터치 설정 확인', '모바일 조작 정의가 모든 기기의 성능 보장은 아닙니다.'), ('기기를 바꾸니 진행이 안 보임', '기존 브라우저를 보존하고 계정 전환 확인', '새 게스트를 만들면 기존 세션이 자동 복구되는 것은 아닙니다.'), ('로딩 실패', '표시된 버전·오류·브라우저를 기록', '저장 데이터를 지우는 것을 첫 해결책으로 쓰지 마세요.')]) + f'<p>원작 개인정보 안내는 게스트가 60일 동안 사용되지 않으면 삭제된다고 설명합니다. 장기 보관이 필요하면 기존 세션에 접근할 수 있을 때 계정 전환을 확인하세요. 복구 성공을 검증한 것은 아닙니다.{ref(2)}</p><p>이 사이트의 Play 창은 다른 제공자의 v0.8.27 게임입니다. 원작과 계정·저장이 같다고 가정하지 마세요.</p>')],
        [ko, legal, client], [('starters/', '스타터 상세 비교 (영어)'), ('multiplayer/', '협동 조건 (영어)'), ('mobile/', '모바일 문제 확인 (영어)')], lang='ko')
    article('es/mobile', 'PokeBonk en móvil: jugar sin APK y conservar tu sesión', 'PokeBonk en móvil sin perder de vista tu sesión',
        'Abre PokeBonk en Android o iPhone sin descargar un APK. Distingue controles, fallos de carga y sesiones antes de cambiar de navegador o borrar datos.',
        f'Para jugar en Android o iPhone, abre el juego original en el navegador. El proyecto dice que no distribuye descargas ni versiones en tiendas. Antes de cambiar de navegador, conserva el acceso a tu sesión de invitado.{ref(1)}{ref(2)}', [
        ('open', 'Entrar sin instalar un archivo', f'<ol><li>Abre {ext(es[0], "pokebonk.com — original en español")} en el teléfono.</li><li>Si ya tienes progreso, usa el mismo navegador y perfil. Si empiezas de cero, elige la entrada de invitado disponible.</li><li>Prueba la orientación horizontal para separar la zona de movimiento, la cámara y las acciones.</li><li>Comprueba movimiento y botones antes de iniciar una sesión larga.</li></ol><p>JavaScript y WebGL son requisitos del sitio. No publicamos requisitos mínimos de RAM ni una lista de teléfonos compatibles: no los hemos verificado.</p>'),
        ('download', 'APK, acceso directo y juego de terceros', table(['Ruta', 'Qué implica', 'Qué comprobar'], [('Web original', 'Juego en el navegador, sin instalador', 'Dominio pokebonk.com y sesión existente.'), ('Añadir a inicio', 'Opción del navegador si está disponible', 'Es un acceso web; no prueba una app nativa ni juego sin conexión.'), ('APK o tienda externa', 'Distribución ajena a la vía descrita por el autor', 'No dar por oficial un archivo por su nombre o icono.'), ('Play en esta guía', 'Fuente de terceros v0.8.27', 'Cuenta y progreso independientes; no usarla como recuperación del original.')]) + f'<p>La declaración sobre distribución pertenece al autor y fue revisada el 28 de octubre. No es una auditoría de cada web o archivo externo.{ref(2)}</p>'),
        ('triage', 'Decidir por el síntoma', table(['Síntoma', 'Primera comprobación', 'Límite de la conclusión'], [('La página no llega al menú', 'Anota error, versión y navegador; comprueba JavaScript/WebGL.', 'No demuestra que tu cuenta se haya borrado.'), ('Aparece el menú pero no responde el movimiento', 'Revisa el foco del juego y la configuración táctil.', 'No mezcles un fallo de entrada con un fallo de servidor.'), ('Se ve la partida pero cuesta leerla', 'Revisa las opciones gráficas; cambia una por vez.', 'Ocultar efectos no garantiza más FPS en tu teléfono.'), ('Falta progreso en otro navegador', 'Vuelve al perfil original antes de crear otro invitado.', 'El servidor puede guardar progreso sin que el nuevo navegador tenga tu sesión.')]) + f'<p>El cliente v0.8.55 define movimiento táctil, cámara y botones de acción. Es una inspección de código del 26 de octubre, no una prueba física de Android o iPhone; la entrada original indica v0.8.62 el día 28.{ref(3)}</p>'),
        ('save', 'Antes de borrar datos o cambiar de dispositivo', f'<p>Conserva la sesión actual mientras compruebas la opción del juego para convertir el invitado en cuenta. La política describe almacenamiento local para la sesión y ajustes, y eliminación del invitado tras 60 días sin uso. No hemos probado recuperación ni ese plazo.{ref(2)}</p><p>Si necesitas ayuda, comunica versión, navegador y el texto del error al soporte enlazado por el original. No envíes contraseñas. Esta guía no puede recuperar cuentas del juego.</p>')],
        [es, legal, client], [('mobile/', 'Más controles y opciones (inglés)'), ('beginners-guide/', 'Primera partida (inglés)')], lang='es')
    article('steam-deck', 'PokeBonk on Steam Deck: Browser Setup & Input Checks', 'Set up PokeBonk on Steam Deck',
        'Compare reported Brave and Heroic browser routes for PokeBonk on Steam Deck, map essential actions and separate stuck movement from loading problems.',
        f'Use the original browser game, then choose either the game’s controller bindings or a deliberate keyboard-and-mouse layout. A Steam Deck thread describes Brave and Heroic routes, but also reports stuck movement while turning the camera. This is a setup checklist based on those reports, not a Deck performance test.{ref(1)}', [
        ('routes', 'Choose a reported browser route', f'<p>R3APER_PL’s r/SteamDeck post and replies, read October 28, describe these routes. They omit the game build and Deck hardware revision. The two routes come from different users in one thread, not independent benchmark datasets.{ref(1)}</p>' + table(['Route', 'Reported sequence', 'Before committing'], [('Brave / R3APER_PL', 'Install Brave in Desktop Mode, add it to Steam, return to Gaming Mode and open pokebonk.com in kiosk mode.', 'Verify the browser opens normally first. Keep its existing launcher command; the post’s Flatpak command is specific to that installation.'), ('Heroic / another commenter', 'Install Heroic, add a URL entry, first open it in Desktop Mode to log in, then try Gaming Mode.', 'Treat this as a reported alternative. We have not verified Heroic’s current URL-entry UI or session transfer.')]) + f'<p>Open {ext("https://pokebonk.com/?lang=en", "pokebonk.com — original browser game")} first. No ROM, Megabonk mod or Windows game executable is part of the original browser route.{ref(2)}</p>'),
        ('controls', 'Map the actions before a long run', '<p>The OP maps movement to WASD, camera to mouse, A to E, X to R, a trigger to Space and other buttons to clicks or scrolling. Use that as a starting layout, then add missing actions rather than copying it as a complete preset.</p>' + table(['Action to keep reachable', 'Keyboard layout target', 'Check'], [('Movement / camera', 'WASD / mouse', 'Move and turn together, then release both; movement should stop.'), ('Jump / slide', 'Space / Left Shift', 'The reported layout lacks an explicit slide binding; assign one if using keyboard emulation.'), ('Interact / Ultimate', 'E / R', 'Test a prompt and Ultimate availability separately.'), ('Map / pause menu', 'M / P', 'Keep menu navigation and a way back to Steam accessible.')]) + f'<p>Those keyboard defaults come from the v0.8.55 public client. If using native gamepad input, inspect the game’s own bindings instead of layering the same action through both schemes. The current menu and any saved rebinding take priority.{ref(3)}</p>'),
        ('stuck', 'If movement sticks while the camera turns', f'<p>The OP reports continued movement until the analog stick is moved in that direction again. A second participant also asks about this symptom; a reply suggests Heroic/Gaming Mode, but the OP says Brave in Gaming Mode still shows it. The thread therefore does not establish a universal fix.{ref(1)}</p><ol><li>In a low-risk area, check movement alone, camera alone, then both together.</li><li>Record whether your layout emits gamepad input, keyboard/mouse input or both. Temporarily compare one input scheme at a time.</li><li>Check whether the same profile behaves differently in Desktop Mode and Gaming Mode. Change one setting at a time.</li><li>If the issue remains, report browser, launcher, game version, input layout and the exact reproduction sequence.</li></ol><p>These are diagnostic comparisons, not confirmed repairs. Do not erase site data to troubleshoot a directional input problem.</p>'),
        ('save', 'Preserve the browser profile and set expectations', f'<p>A new launcher or browser can have a separate session. Keep the working profile until you confirm access to the same game account. The original policy describes local session storage and deletion of inactive Guests after 60 days; it does not promise that different launchers share credentials.{ref(2)}</p><p>Two users in the thread describe playing on Deck, but no reproducible FPS, battery, full-run or co-op measurements are supplied. We did not test a physical Deck. The original entry is v0.8.62 on October 28; the source for the action table is explicitly v0.8.55.</p>')],
        [report, legal, client], [('mobile/', 'Phone and controller checks'), ('troubleshooting/', 'Separate loading and account errors'), ('beginners-guide/', 'First-run checklist')])
    for slug in ['ko/beginners-guide', 'es/mobile', 'steam-deck']:
        path = P + slug + '/'
        # These setup articles do not need unrelated promotional artwork.
        pages[path]['html'] = re.sub(r'<figure>.*?</figure>', '', pages[path]['html'], flags=re.S)
        pages[path]['html'] = re.sub(r'<meta property="og:image"[^>]+>', '', pages[path]['html'])
    ctx['DATE'], ctx['VERSION'] = old_date, old_version
    beginner = pages[P+'beginners-guide/']['html']
    beginner = beginner.replace('<section class="related">', '<section id="cheats"><h2>Cheats, trainers and account rules</h2><p>Checked October 28: the original project prohibits modifying the game, automating runs or manipulating server communications. Its stated consequences include removal from rankings and possible suspension. We have not verified an authorized cheat menu, trainer or account-unlock tool. For progression, use the <a href="/pokebonk/unlocks/">League requirements</a> and <a href="/pokebonk/lab/">Lab cost decisions</a> instead of treating a third-party download as an official shortcut.'+ref(3)+'</p></section><section class="related">', 1)
    pages[P+'beginners-guide/']['html'] = beginner
    for slug, fragment in [('mobile', '<p><a href="/pokebonk/es/mobile/">Español: móvil y descarga</a> · <a href="/pokebonk/steam-deck/">Steam Deck setup and stuck-input checks</a></p>'), ('beginners-guide', '<p><a href="/pokebonk/ko/beginners-guide/">한국어: 포케봉크 시작 방법</a></p>')]:
        pages[P+slug+'/']['html'] = pages[P+slug+'/']['html'].replace('<section class="related">', fragment+'<section class="related">', 1)
    # A short identity question belongs with the existing identity answer.
    home = pages[P]['html']
    marker = '<h3>Was PokeBonk made with AI?</h3><p>Checked October 28, 2026: the author’s legal notice attributes scenery, 3D assets, effects, interface icons and music to image/audio generation tools and Blender. It separately credits community Pokémon sprites. That statement describes asset provenance; it does not establish which proportion of the code used AI or certify the safety of other websites. See the existing legal source below.</p>'
    marker = marker.replace('See the existing legal source below.', ref(3))
    home = home.replace('<section class="sources"', '<section id="ai"><h2>AI and asset credits</h2>'+marker+'</section><section class="sources"', 1)
    home = home.replace('Fan-project status and Guest policy, accessed October 23.', 'Fan-project status, asset provenance and Guest policy; legal notice rechecked October 28.')
    home = home.replace('<div class="guide-index">', '<div class="guide-index"><a href="/pokebonk/ko/beginners-guide/" lang="ko">한국어 시작 가이드<span>게스트·스타터·조작·저장 확인</span></a><a href="/pokebonk/es/mobile/" lang="es">Móvil y descarga en español<span>Entrar sin APK y conservar la sesión</span></a><a href="/pokebonk/steam-deck/">Steam Deck setup<span>Browser routes, action layout and stuck-input reports</span></a>', 1)
    pages[P]['html'] = home
